+/** Build the durable operation document for a validated batch without persisting or executing it. */
+export function planBatch(spec: unknown, options: { id?: string; resources: ResourceDescriptor[]; now: number }): DurableOperationState {
+  const batch = validateBatchSpec(spec);
+  return newOperation(options.id ?? batch.id ?? `batch-${Date.now()}`, batch.objective, batch.units, options.resources, options.now, batch.policy);
